int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Calculate the size of the message
    int size = schema.getSerializedSize(message, buffer);

    // Write the size as a VarInt
    ProtobufOutputOutput.computeRawVarint32Size(size);
    buffer = ProtobufOutputOutput.writeRawVarint32(size, buffer);

    // Serialize the message
    buffer = schema.writeTo(out, message, buffer);

    // Check if buffer is complete
    if (buffer.start != buffer.offset) {
        out.write(buffer.buffer, buffer.start, buffer.offset - buffer.start);
    }

    return size;
}

int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.newMessageBuffer();
    final int size = schema.writeTo(buffer, message);
    buffer.getWriterIndex(size);
    ProtostuffIOUtil.writeGraphTag(size, out);
    LinkedBuffer.writeTo(out, data, 0, size);
    return size;
}

int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.toByteArray(message, buffer);
    int size = data.length;
    ProtobufVarintEncoder.writeRawVarint32(out, size);
    out.write(data);
    return size;
}

