static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    int adjustedDay = ((dayOfMonth - 1) / dayStep) * dayStep + 1;

    return year * 10000 + month * 100 + adjustedDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the first day of the current month
    int firstDayOfMonth = 1;

    // Calculate the offset to find the nearest previous day that is a multiple of dayStep
    int offset = (dayOfMonth - firstDayOfMonth) % dayStep;
    if (offset != 0) {
        dayOfMonth -= offset;
    }

    // Ensure dayOfMonth is not zero
    if (dayOfMonth == 0) {
        dayOfMonth = firstDayOfMonth;
    }

    return year * 10000 + month * 100 + dayOfMonth;
}

