    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the starting day of the month
    int startDay = 1;
    if (dayOfMonth <= dayStep) {
        return timeBucket - (dayOfMonth - startDay);
    } else {
        int newDay = ((dayOfMonth - 1) / dayStep) * dayStep + 1;
