long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    int adjustedDay = ((dayOfMonth - 1) / dayStep) * dayStep + 1;

    return year * 10000 + month * 100 + adjustedDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        char c = str.charAt(i++);
        if (c >= 0 && c <= 127) {
            size++;
        } else if (c > 2047) {
            size += 3;
        } else {
            size += 2;
        }
    }
    return size;
}

