LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    int utflen = 0;
    int c;

    /* use charAt instead of copying String to char array */
    for (int i = 0; i < len; i++) {
        c = str.charAt(i);
        if ((c >= 0x0001) && (c <= 0x007F)) {
            utflen++;
        } else if (c > 0x07FF) {
            utflen += 3;
        } else {
            utflen += 2;
        }
    }

    if (utflen > lb.buffer.length - lb.offset) {
        lb = session.next(lb, utflen);
    }

    byte[] bytes = lb.buffer;
    int count = lb.offset;

    for (int i = 0; i < len; i++) {
        c = str.charAt(i);
        if ((c >= 0x0001) && (c <= 0x007F)) {
            bytes[count++] = (byte) c;
        } else if (c > 0x07FF) {
            bytes[count++] = (byte) (0xE0 | ((c >> 12) & 0x0F));
            bytes[count++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[count++] = (byte) (0x80 | ((c) & 0x3F));
        } else {
            bytes[count++] = (byte) (0xC0 | ((c >> 6) & 0x1F));
            bytes[count++] = (byte) (0x80 | ((c) & 0x3F));
        }
    }

    lb.offset = count;
    return lb;
}

