private void pop(final String descriptor){
    // Assuming descriptor is a method descriptor, we need to pop the argument types
    if (descriptor.charAt(0) == '(') {
        int index = 1; // Start after the opening parenthesis
        while (descriptor.charAt(index) != ')') {
            char c = descriptor.charAt(index);
            switch (c) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // These are single-slot types
                    index++;
                    break;
                case 'J': case 'D':
                    // These are double-slot types
                    index++;
                    break;
                case 'L':
                    // Object type, read until ';'
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    index++; // Move past the ';'
                    break;
                case '[':
                    // Array type, skip to the end of the array descriptor
                    while (descriptor.charAt(index) == '[') {
                        index++;
                    }
                    // Now we should have a type descriptor, handle it like a non-array type
                    if (descriptor.charAt(index) == 'L') {
                        while (descriptor.charAt(index) != ';') {
                            index++;
                        }
                        index++; // Move past the ';'
                    } else {
                        index++;
                    }
                    break;
                default:
                    throw new RuntimeException("Invalid descriptor: " + descriptor);
            }
            // Pop the type from the stack (assuming there's a method to do this)
            popTypeFromStack();
        }
    } else {
        // Single type descriptor, pop accordingly
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                popInt();
                break;
            case 'J':
                popLong();
                break;
            case 'D':
                popDouble();
                break;
            case 'L':
                popObject();
                break;
            case '[':
                popArray();
                break;
            default:
                throw new RuntimeException("Invalid descriptor: " + descriptor);
        }
    }
}

