        int currentIdx = 1;
        while (descriptor.charAt(currentIdx) != ')') {
            currentIdx = consumeTypeDescriptor(descriptor, currentIdx);
        }
    } else {
        // It's a field descriptor, pop a single type
        consumeTypeDescriptor(descriptor, 0);
    }
}

private void pop(final String descriptor){
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, extract the argument types
        int end = descriptor.indexOf(')');
        String argumentTypes = descriptor.substring(1, end);
        for (int i = 0; i < argumentTypes.length(); ) {
            char c = argumentTypes.charAt(i++);
            switch (c) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // All these types take up one slot
                    popFrame();
                    break;
                case 'D': case 'J':
                    // Double and long take up two slots
                    popFrame();
                    popFrame();
                    break;
                case 'L':
                    // Object types, skip the class name
                    while (argumentTypes.charAt(i) != ';') i++;
                    i++; // Move past the ';'
                    popFrame();
                    break;
                case '[':
                    // Arrays, skip the array dimensions
                    while (argumentTypes.charAt(i) == '[') i++;
                    c = argumentTypes.charAt(i++);
                    if (c == 'L') {
                        // Array of objects, skip the class name
                        while (argumentTypes.charAt(i) != ';') i++;
                    }
                    popFrame();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } else {
        // It's a type descriptor
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                popFrame();
                break;
            case 'D': case 'J':
                popFrame();
                popFrame();
                break;
            case 'L':
                // Object types
                popFrame();
                break;
            case '[':
                // Arrays
                popFrame();
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

void pop(final String descriptor) {
    int stackIndex = typeStack.size() - 1;
    switch (descriptor.charAt(0)) {
        case 'V':
            break; // void type, do nothing
        case 'D':
        case 'J':
            typeStack.remove(stackIndex);
            typeStack.remove(stackIndex - 1);
            break; // double or long types take up two slots
        case '[':
        case 'L':
            typeStack.remove(stackIndex);
            break; // array or object type
        case '(':
            // Method descriptor, parse and pop argument types
            int i = descriptor.indexOf(')');
            String argTypes = descriptor.substring(1, i);
            while (!argTypes.isEmpty()) {
                switch (argTypes.charAt(0)) {
                    case 'D':
                    case 'J':
                        typeStack.remove(stackIndex);
                        typeStack.remove(stackIndex - 1);
                        argTypes = argTypes.substring(1);
                        break;
                    case '[':
                        // Array type
                        int arrayDim = 1;
                        while (argTypes.charAt(arrayDim) == '[') arrayDim++;
                        if (argTypes.charAt(arrayDim) == 'L') {
                            // Object array
                            int endIndex = argTypes.indexOf(';', arrayDim);
                            arrayDim = endIndex + 1;
                        }
                        typeStack.remove(stackIndex);
                        argTypes = argTypes.substring(arrayDim);
                        break;
                    case 'L':
                        // Object type
                        int endIndex = argTypes.indexOf(';', 1);
                        typeStack.remove(stackIndex);
                        argTypes = argTypes.substring(endIndex + 1);
                        break;
                    default:
                        // Primitive type
                        typeStack.remove(stackIndex);
                        argTypes = argTypes.substring(1);
                        break;
                }
                stackIndex--;
            }
            break;
        default:
            typeStack.remove(stackIndex);
            break; // default to popping one slot
    }
}

private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the end of argument descriptors
        index = descriptor.indexOf(')');
        String argsDescriptor = descriptor.substring(1, index);
        index += 1; // Skip the ')'
        while (!argsDescriptor.isEmpty()) {
            char argType = argsDescriptor.charAt(0);
            if (argType == 'J' || argType == 'D') {
                // double and long types take two slots
                popFrame();
                popFrame();
            } else if (argType == '[' || argType == 'L') {
                // array and object types take one slot
                popFrame();
                int semi = argsDescriptor.indexOf(';');
                if (semi != -1) {
                    argsDescriptor = argsDescriptor.substring(semi + 1);
                } else {
                    argsDescriptor = "";
                }
            } else {
                // single-slot types
                popFrame();
            }
            if (argsDescriptor.length() > 0) {
                argsDescriptor = argsDescriptor.substring(1);
            }
        }
    } else {
        // It's a type descriptor
        char type = descriptor.charAt(0);
        if (type == 'J' || type == 'D') {
            // double and long types take two slots
            popFrame();
            popFrame();
        } else {
            // single-slot types
            popFrame();
        }
    }
}

