public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder writer = new StringBuilder(str.length());
    int sz = str.length();
    int i = 0;
    while (i < sz) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (++i >= sz) {
                throw new Exception("Invalid escape character at end of string");
            }
            ch = str.charAt(i);
            switch (ch) {
                case 'b':
                    writer.append('\b');
                    break;
                case 'n':
                    writer.append('\n');
                    break;
                case 't':
                    writer.append('\t');
                    break;
                case 'f':
                    writer.append('\f');
                    break;
                case 'r':
                    writer.append('\r');
                    break;
                case '"':
                    writer.append('"');
                    break;
                case '\'':
                    writer.append('\'');
                    break;
                case '\\':
                    writer.append('\\');
                    break;
                case 'u':
                    if (i + 4 > sz) {
                        throw new Exception("Malformed Unicode escape sequence at end of string");
                    }
                    int value = 0;
                    for (int j = 0; j < 4; j++) {
                        ch = str.charAt(++i);
                        switch (ch) {
                            case '0':
                            case '1':
                            case '2':
                            case '3':
                            case '4':
                            case '5':
                            case '6':
                            case '7':
                            case '8':
                            case '9':
                                value = (value << 4) + ch - '0';
                                break;
                            case 'a':
                            case 'b':
                            case 'c':
                            case 'd':
                            case 'e':
                            case 'f':
                                value = (value << 4) + 10 + ch - 'a';
                                break;
                            case 'A':
                            case 'B':
                            case 'C':
                            case 'D':
                            case 'E':
                            case 'F':
                                value = (value << 4) + 10 + ch - 'A';
                                break;
                            default:
                                throw new Exception("Invalid Unicode escape sequence at index " + i);
                        }
                    }
                    writer.append((char) value);
                    break;
                default:
                    throw new Exception("Invalid escape character " + ch);
            }
        } else {
            writer.append(ch);
        }
        i++;
    }
    return writer.toString();
}

