public static String applyRelativePath(String path, String relativePath) {
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (pathParts.length > 0) {
                pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
            }
        } else if (!part.equals(".")) {
            String[] newPathParts = new String[pathParts.length + 1];
            System.arraycopy(pathParts, 0, newPathParts, 0, pathParts.length);
            newPathParts[pathParts.length] = part;
            pathParts = newPathParts;
        }
    }

    return String.join("/", pathParts);
}

public static String applyRelativePath(String path, String relativePath) {
    java.nio.file.Path basePath = java.nio.file.Paths.get(path);
    java.nio.file.Path resolvedPath = basePath.resolve(relativePath);
    return resolvedPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // If the relative path starts with "/", it's an absolute path, return it directly
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a list to make manipulation easier
    List<String> resultComponents = new ArrayList<>(Arrays.asList(pathComponents));

    // Process each component in the relative path
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            // Stay in the current directory, do nothing
        } else if (component.equals("..")) {
            // Move up one directory if possible
            if (resultComponents.size() > 0 && !resultComponents.get(resultComponents.size() - 1).isEmpty()) {
                resultComponents.remove(resultComponents.size() - 1);
            }
        } else {
            // Add the component to the current path
            resultComponents.add(component);
        }
    }

    // Join the components back into a single path
    return String.join("/", resultComponents);
}

